	[Header("Battle Actions")]
	public List<BattleAction> battleActions = new List<BattleAction>();

	public BattleAction GetBattleAction(string battleActionName)
	{
		string text = battleActionName.Replace(" ", "").Replace("Action", "");
		if (actionsChangedPostReleaseDictionary.ContainsKey(text))
		{
			text = actionsChangedPostReleaseDictionary[text];
		}
		text = text.ToLower();
		for (int i = 0; i < battleActions.Count; i++)
		{
			if (text == battleActions[i].name.Replace("Action", "").ToLower())
			{
				return battleActions[i];
			}
		}
		text = battleActionName.Replace(" ", "").ToLower();
		for (int j = 0; j < battleActions.Count; j++)
		{
			if (text == battleActions[j].name.ToLower())
			{
				return battleActions[j];
			}
		}
		Debug.Log("Battle Action: " + battleActionName + " not found. Searching Name: " + text);
		return null;
	}
